// Order the vertices 0 .. n-1 of a directed graph so that for every pair
// (a, b) in deps, a comes before b. Duplicate pairs are allowed.
//
// If such an order exists, return (true, order) where order is the
// lexicographically smallest valid order (at each step, the smallest vertex
// whose predecessors are all placed).
//
// If the graph has a cycle (a pair (a, a) is a cycle of one vertex), return
// (false, cycle): let s be the smallest vertex that lies on any cycle; cycle
// is the shortest cycle through s, written as its vertices starting at s
// without repeating s at the end; among shortest cycles, the
// lexicographically smallest list.
//
// Invalid input (n < 0, or any vertex in deps outside 0 .. n-1) returns
// (false, []), even if the graph also has a cycle. n == 0 gives (true, []).
//
// Examples:
//   topo_order(4, [(0, 1), (0, 2), (1, 3), (2, 3)]) == (true, [0, 1, 2, 3])
//   topo_order(3, [(0, 1), (1, 2), (2, 0)]) == (false, [0, 1, 2])
fn topo_order(n: Int, deps: List[(Int, Int)]) -> (Bool, List[Int]) {
  if n < 0 || any(deps, |d| d.0 < 0 || d.0 >= n || d.1 < 0 || d.1 >= n) {
    return (false, []);
  }
  let mut indeg: Map[Int, Int] = map_from_list(map(range(0, n), |v| (v, 0)));
  for (_, b) in deps {
    indeg = map_set(indeg, b, indeg[b] + 1);
  }
  let mut order: List[Int] = [];
  let mut used: Set[Int] = set_new();
  let mut going = true;
  while going {
    let ready = filter(range(0, n), |v| !set_contains(used, v) && indeg[v] == 0);
    match head(ready) {
      None => {
        going = false;
      },
      Some(v) => {
        order = push(order, v);
        used = set_add(used, v);
        for (a, b) in deps {
          if a == v {
            indeg = map_set(indeg, b, indeg[b] - 1);
          }
        }
      },
    }
  }
  if len(order) == n {
    return (true, order);
  }
  for s in range(0, n) {
    let found = shortest_cycle(deps, s);
    if !is_empty(found) {
      return (false, found);
    }
  }
  (false, [])
}

// BFS from s with sorted successors: the first edge back to s closes the
// lexicographically smallest shortest cycle. [] if s is on no cycle.
fn shortest_cycle(deps: List[(Int, Int)], s: Int) -> List[Int] {
  let mut parent: Map[Int, Int] = map_from_list([(s, -1)]);
  let mut queue = [s];
  let mut qi = 0;
  while qi < len(queue) {
    let u = queue[qi];
    qi = qi + 1;
    for w in unique(sort(map(filter(deps, |d| d.0 == u), |d| d.1))) {
      if w == s {
        let mut cycle = [u];
        let mut x = u;
        while parent[x] != -1 {
          x = parent[x];
          cycle = push(cycle, x);
        }
        return reverse(cycle);
      }
      if !map_contains(parent, w) {
        parent = map_set(parent, w, u);
        queue = push(queue, w);
      }
    }
  }
  []
}
